mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "required": ["appName", "environment"],
  "properties": {
    "appName": {
      "type": "string",
      "description": "Name of the MuleSoft application as it appears in Anypoint Runtime Manager."
    },
    "environment": {
      "type": "string",
      "description": "Anypoint Platform environment where the app is running (e.g. Production, Staging, Development)."
    },
    "jiraTicketId": {
      "type": "string",
      "description": "Optional Jira ticket ID to link assessment results back to a migration tracking ticket."
    },
    "branch": {
      "type": "string",
      "description": "Optional. Explicit branch to assess for this request. Highest precedence — overrides the registry default and the repository's discovered default branch."
    },
    "owner": {
      "type": "string",
      "description": "Optional GitHub owner/org override (used only when the app is not in the registry)."
    },
    "repo": {
      "type": "string",
      "description": "Optional GitHub repository name override (used only when the app is not in the registry)."
    },
    "appPath": {
      "type": "string",
      "description": "Optional path to the Mule module within the repo (e.g. \".\" for repo root)."
    },
    "orgId": {
      "type": "string",
      "description": "Optional Anypoint organization ID override (used only when the app is not in the registry)."
    }
  }
}

{
  "type": "object",
  "required": ["appName", "environment"],
  "properties": {
    "appName": {
      "type": "string",
      "description": "Name of the MuleSoft application to upgrade."
    },
    "environment": {
      "type": "string",
      "description": "Anypoint Platform environment to upgrade the application in."
    },
    "jiraTicketId": {
      "type": "string",
      "description": "Jira ticket ID for this migration effort. Progress updates will be posted to this ticket."
    },
    "approvedChangePlan": {
      "type": "object",
      "description": "The changePlan object returned by assess_app, reviewed and approved by the user.",
      "properties": {
        "targetRuntime":     { "type": "string" },
        "targetJavaVersion": { "type": "string" },
        "filesToChange":     { "type": "array", "items": { "type": "string" } },
        "hasApiPolicies":    { "type": "boolean" },
        "hasCustomJavaCode": { "type": "boolean" },
        "hasLookupFunction": { "type": "boolean" }
      }
    },
    "branch": {
      "type": "string",
      "description": "Optional. Explicit branch to upgrade for this request. Highest precedence — overrides the registry default and the repository's discovered default branch."
    },
    "owner": {
      "type": "string",
      "description": "Optional GitHub owner/org override (used only when the app is not in the registry)."
    },
    "repo": {
      "type": "string",
      "description": "Optional GitHub repository name override (used only when the app is not in the registry)."
    },
    "appPath": {
      "type": "string",
      "description": "Optional path to the Mule module within the repo (e.g. \".\" for repo root)."
    },
    "orgId": {
      "type": "string",
      "description": "Optional Anypoint organization ID override (used only when the app is not in the registry)."
    }
  }
}

{
  "type": "object",
  "required": ["jobId"],
  "properties": {
    "jobId": {
      "type": "string",
      "description": "The jobId returned by start_upgrade. Format: job-{uuid}."
    }
  }
}
